"""Regenerates supabase/schema.sql seed section from data/catalog.json + data/learned/learned-examples.json."""
import json, pathlib
root = pathlib.Path(__file__).resolve().parent.parent
cat = json.load(open(root / "data/catalog.json")); ex = json.load(open(root / "data/learned/learned-examples.json"))["examples"]
q = lambda v: "null" if v in (None, "") else "'" + str(v).replace("'", "''") + "'"
j = lambda v: "'" + json.dumps(v, ensure_ascii=False).replace("'", "''") + "'::jsonb"
F = ["catalog_id","category","object_type","material","color","length_mm","width_mm","thickness_mm","weight_g","measure_method","condition","key_features","suggestion_1","suggestion_2","suggestion_3","confidence","owner_observations","open_questions","date_found","context_notes","location_sharing","status","era","geologic_period","formation","preservation","hardness","luster","streak","category_note"]
out = ["-- ===== 4. SEED (generated by supabase/gen_seed.py; safe to re-run: existing rows are left untouched) ====="]
for r in cat:
    ann = {str(i): p["annotations"] for i, p in enumerate(r.get("photos", [])) if p.get("annotations")}
    out.append(f"insert into public.finds ({', '.join(F)}, annotations, category_history, is_public) values ({', '.join(q(r.get(k)) for k in F)}, {j(ann)}, {j(r.get('category_history', []))}, true) on conflict (catalog_id) do nothing;")
    for i, p in enumerate(r.get("photos", [])):
        out.append(f"insert into public.photos (catalog_id, sort, repo_path, thumb_path, view, label, is_public) values ({q(r['catalog_id'])}, {i}, {q(p['path'])}, {q(p.get('thumb'))}, {q(p.get('view'))}, {q(p.get('label'))}, true) on conflict (catalog_id, sort) do nothing;")
for e in ex:
    out.append(f"insert into public.verified_examples (catalog_id, category, confirmed_type, type_ids, features, length_mm, material, confirmed_on, source, is_public) values ({q(e['catalog_id'])}, {q(e['category'])}, {q(e['confirmed_type'])}, array[{', '.join(q(t) for t in e['type_ids'])}]::text[], {q(e['features'])}, {q(e['length_mm'])}, {q(e['material'])}, {q(e['confirmed_on'])}, {q(e['source'])}, true) on conflict (catalog_id) do nothing;")
s = (root / "supabase/schema.sql").read_text(); m = "-- ===== 4. SEED"
s = s[:s.index(m)] if m in s else s
(root / "supabase/schema.sql").write_text(s + "\n".join(out) + "\n\ncommit;\n")
